import java.util.*;import java.util.zip.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;
public final class InspectSiteNonTimestampSupport {
 public static void main(String[]args)throws Exception{try(var zip=new ZipFile(args[0])){for(var entry:Collections.list(zip.entries()))if(entry.getName().matches("classes[0-9]*\\.dex"))try(var in=zip.getInputStream(entry)){var dex=new DexBackedDexFile(Opcodes.getDefault(),java.nio.ByteBuffer.wrap(in.readAllBytes()));for(ClassDef type:dex.getClasses())for(Method method:type.getMethods())if(method.getParameterTypes().equals(List.of("J"))&&method.getReturnType().equals("Z")&&method.getImplementation()!=null)for(Instruction instruction:method.getImplementation().getInstructions())if(instruction instanceof WideLiteralInstruction literal&&literal.getWideLiteral()==9240000000L){System.out.println(method);break;}}}}
}
